def transform(grid):
    from collections import Counter, deque
    g=[row[:] for row in grid]
    cnt=Counter(v for row in g for v in row if v not in (0,5))
    bg=cnt.most_common(1)[0][0]
    h,w=len(g),len(g[0]); q=deque(); seen=set()
    for r in range(h):
        for c in range(w):
            if g[r][c]==5:
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<h and 0<=nc<w and g[nr][nc]==bg and (nr,nc) not in seen:
                            seen.add((nr,nc));q.append((nr,nc))
    while q:
        r,c=q.popleft();g[r][c]=5
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                nr,nc=r+dr,c+dc
                if 0<=nr<h and 0<=nc<w and g[nr][nc]==bg and (nr,nc) not in seen:
                    seen.add((nr,nc));q.append((nr,nc))
    return g
PY

